@Test
public void test() throws Exception {
    File outputFile = new File(folder.getRoot(), "dump-output.txt");
    AnalysisEngine writer = AnalysisEngineFactory.createEngine(CasDumpWriter.class, CasDumpWriter.PARAM_OUTPUT_FILE, outputFile.getPath());
    JCas jcas = writer.newJCas();
    CasIOUtil.readJCas(jcas, new File("src/test/resources/data/docs/test.xmi"));
    writer.process(jcas);
    assertTrue(outputFile.exists());
    String reference = readFileToString(new File("src/test/resources/data/reference/test.xmi.dump"), "UTF-8").trim();
    String actual = readFileToString(outputFile, "UTF-8").trim();
    actual = actual.replaceAll("\r\n", "\n");
    assertEquals(reference, actual);
}

