/**
 * This test demonstrates that running the viewCreator is doing the right thing (i.e. initializing
 * the view "myView")
 */
@Test
public void testSofaInitializer() throws ResourceInitializationException, AnalysisEngineProcessException, CASException {
    AnalysisEngineDescription description = AnalysisEngineFactory.createEngineDescription(SofaAwareAnnotator.class, typeSystemDescription);
    AnalysisEngine engine = AnalysisEngineFactory.createEngine(description, "myView");
    AnalysisEngine viewCreator = AnalysisEngineFactory.createEngine(ViewCreatorAnnotator.class, typeSystemDescription, ViewCreatorAnnotator.PARAM_VIEW_NAME, "myView");
    viewCreator.process(jCas);
    engine.process(jCas);
    assertEquals("some", JCasUtil.selectByIndex(jCas.getView("myView"), Token.class, 0).getCoveredText());
    // here I run again with viewCreator running twice to make sure it
    // does the right thing when the view
    // has already been created
    jCas.reset();
    viewCreator.process(jCas);
    viewCreator.process(jCas);
    engine.process(jCas);
    assertEquals("some", JCasUtil.selectByIndex(jCas.getView("myView"), Token.class, 0).getCoveredText());
    description = AnalysisEngineFactory.createEngineDescription(SofaUnawareAnnotator.class, typeSystemDescription);
    engine = AnalysisEngineFactory.createEngine(description, "myView");
    jCas.reset();
    viewCreator.process(jCas);
    engine.process(jCas);
    assertEquals("some", JCasUtil.selectByIndex(jCas.getView("myView"), Token.class, 0).getCoveredText());
    jCas.reset();
    viewCreator.process(jCas);
    viewCreator.process(jCas);
    engine.process(jCas);
    assertEquals("some", JCasUtil.selectByIndex(jCas.getView("myView"), Token.class, 0).getCoveredText());
}

@Test
public void testViewTextCopier() throws ResourceInitializationException, AnalysisEngineProcessException, CASException {
    String text = "sample text";
    String sourceViewName = "SourceView";
    String destinationViewName = "DestinationView";
    jCas.setDocumentText(text);
    AnalysisEngine viewCreator = AnalysisEngineFactory.createEngine(ViewTextCopierAnnotator.class, typeSystemDescription, ViewTextCopierAnnotator.PARAM_SOURCE_VIEW_NAME, CAS.NAME_DEFAULT_SOFA, ViewTextCopierAnnotator.PARAM_DESTINATION_VIEW_NAME, destinationViewName);
    viewCreator.process(jCas);
    JCas destinationView = jCas.getView(destinationViewName);
    assertNotNull(destinationView);
    assertEquals(text, destinationView.getDocumentText());
    jCas.reset();
    jCas.setDocumentText(text);
    jCas.createView(destinationViewName);
    viewCreator.process(jCas);
    destinationView = jCas.getView(destinationViewName);
    assertNotNull(destinationView);
    assertEquals(text, destinationView.getDocumentText());
    viewCreator = AnalysisEngineFactory.createEngine(ViewTextCopierAnnotator.class, typeSystemDescription, ViewTextCopierAnnotator.PARAM_SOURCE_VIEW_NAME, sourceViewName, ViewTextCopierAnnotator.PARAM_DESTINATION_VIEW_NAME, destinationViewName);
    jCas.reset();
    JCas sourceView = jCas.createView(sourceViewName);
    sourceView.setDocumentText(text);
    viewCreator.process(jCas);
    destinationView = jCas.getView(destinationViewName);
    assertNotNull(destinationView);
    assertEquals(text, destinationView.getDocumentText());
    assertNull(jCas.getDocumentText());
}

