@Test(expected = ResourceInitializationException.class)
public void testAAEMultipleDeploymentPolicyProblem() throws Exception {
    {
        AnalysisEngineDescription desc1 = AnalysisEngineFactory.createEngineDescription(PristineAnnotatorClass.class, (Object[]) null);
        assertTrue("Multiple deployment should be allowed on " + desc1.getAnnotatorImplementationName(), desc1.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
