/*
   * This test case illustrates that UIMA throws an exception unless the multipleDeploymentAllowed
   * flag is properly set to false when mixing multi-deployment and non-multi-deployment AEs.
   */
@Test(expected = ResourceInitializationException.class)
public void testAAEMultipleDeploymentPolicyProblem() throws Exception {
    {
        AnalysisEngineDescription desc1 = AnalysisEngineFactory.createEngineDescription(PristineAnnotatorClass.class, (Object[]) null);
        assertTrue("Multiple deployment should be allowed on " + desc1.getAnnotatorImplementationName(), desc1.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
        AnalysisEngineDescription desc2 = AnalysisEngineFactory.createEngineDescription(UnannotatedAnnotatorClass.class, (Object[]) null);
        assertFalse("Multiple deployment should be prohibited on " + desc2.getAnnotatorImplementationName(), desc2.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
        AnalysisEngineDescription aae = AnalysisEngineFactory.createEngineDescription(desc1, desc2);
        aae.getAnalysisEngineMetaData().getOperationalProperties().setMultipleDeploymentAllowed(true);
        UIMAFramework.produceAnalysisEngine(aae);
    }
}

@Test
public void testAAEMultipleDeploymentPolicy() throws Exception {
    {
        AnalysisEngineDescription desc1 = AnalysisEngineFactory.createEngineDescription(PristineAnnotatorClass.class, (Object[]) null);
        assertTrue("Multiple deployment should be allowed on " + desc1.getAnnotatorImplementationName(), desc1.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
        AnalysisEngineDescription desc2 = AnalysisEngineFactory.createEngineDescription(UnannotatedAnnotatorClass.class, (Object[]) null);
        assertFalse("Multiple deployment should be prohibited on " + desc2.getAnnotatorImplementationName(), desc2.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
        AnalysisEngineDescription aae = AnalysisEngineFactory.createEngineDescription(desc1, desc2);
        UIMAFramework.produceAnalysisEngine(aae);
        assertFalse("Multiple deployment should be prohibited on AAE", aae.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
    }
    {
        AnalysisEngineDescription desc1 = AnalysisEngineFactory.createEngineDescription(PristineAnnotatorClass.class, (Object[]) null);
        assertTrue("Multiple deployment should be allowed on " + desc1.getAnnotatorImplementationName(), desc1.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
        AnalysisEngineDescription desc3 = AnalysisEngineFactory.createEngineDescription(AnnotatedAnnotatorClass.class, (Object[]) null);
        assertTrue("Multiple deployment should be allowed  on " + desc3.getAnnotatorImplementationName(), desc3.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
        AnalysisEngineDescription aae = AnalysisEngineFactory.createEngineDescription(desc1, desc3);
        UIMAFramework.produceAnalysisEngine(aae);
        assertTrue("Multiple deployment should be prohibited on AAE", aae.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed());
    }
}

